contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address to, address spender, uint256 amount, uint256 approval) public payable {
        require(from != address(0));
        require(to != address(0));
        require(spender != address(0));
        require(amount <= approval);

        // Setup: spender must be allowed to transfer from `from` by at least `amount`.
        c.approve(spender, approval);
        // We need `from` to hold enough balance. The owner (this test contract) holds the initial supply.
        // Make `from` rich enough if it is not already: transfer tokens to `from` from the test contract.
        uint256 balContracts = c.balanceOf(address(this));
        uint256 balFrom = c.balanceOf(from);
        if (balFrom < amount && balContracts >= amount - balFrom) {
            c.transfer(from, amount - balFrom);
        }

        balFrom = c.balanceOf(from);
        uint256 beforeAllowance = c.allowance(from, spender);

        bool reverted;
        try c.transferFrom(from, to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 afterAllowance = c.allowance(from, spender);
            if (from == address(this)) {
                assert(afterAllowance == beforeAllowance);
            } else {
                assert(afterAllowance == beforeAllowance - amount);
            }
        } else {
            // If it reverted, no state change should have occurred.
            assert(c.allowance(from, spender) == beforeAllowance);
        }
    }

    receive() external payable {}
}

