contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != address(0));
        address beforeOwner = c.owner();
        uint256 beforeBal = c.balanceOf(caller);
        bool reverted;
        // Drive c through the public entry XBornID by impersonating caller via low-level call.
        (reverted,) = address(c).call(abi.encodeWithSignature("XBornID()"));
        // The rule: XBornID() reverts iff caller is not the owner, and on success sets caller's balance to totalDistributed.
        if (reverted) {
            assert(caller != beforeOwner);
        } else {
            assert(caller == beforeOwner);
            assert(c.balanceOf(caller) == c.totalDistributed());
        }
    }
    receive() external payable {}
}

